import{_ as i,a0 as s,w as l,s as r,ao as d,I as n,x as o,a1 as a,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"安卓編年史（28）：Android 5.0 Lollipop——有史以來最重要的安卓版本（2） | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（28）：Android 5.0 Lollipop——有史以來最重要的安卓版本（2） | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（28）：Android 5.0 Lollipop——有史以來最重要的安卓版本（2） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（28）：Android 5.0 Lollipop——有史以來最重要的安卓版本（2） | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/28 - The history of Android","title":"安卓編年史（28）：Android 5.0 Lollipop——有史以來最重要的安卓版本（2）","tag":"The history of Android","desc":""},"relativePath":"The history of Android/28 - The history of Android.md","filePath":"[post].md"}'),g={name:"The history of Android/28 - The history of Android.md"};function h(c,t,m,u,T,f){const e=s("Link");return l(),r("div",null,[t[18]||(t[18]=d('<h1 id="安卓編年史-28-android-5-0-lollipop——有史以來最重要的安卓版本-2" tabindex="-1">安卓編年史（28）：Android 5.0 Lollipop——有史以來最重要的安卓版本（2） <a class="header-anchor" href="#安卓編年史-28-android-5-0-lollipop——有史以來最重要的安卓版本-2" aria-label="Permalink to “安卓編年史（28）：Android 5.0 Lollipop——有史以來最重要的安卓版本（2）”">​</a></h1><h4 id="art——為未來提供了一個平台的安卓運行時" tabindex="-1">ART——為未來提供了一個平台的安卓運行時 <a class="header-anchor" href="#art——為未來提供了一個平台的安卓運行時" aria-label="Permalink to “ART——為未來提供了一個平台的安卓運行時”">​</a></h4><p>安卓裏沒有多少組件的血統能追溯到 1.0 時代，但在 2014 年， Dalvik 這個驅動安卓應用的運行時是它們中的一員。Dalvik 最初是為單核、低端性能設備設計的，而且存儲和內存佔用的優先級要高於性能表現。在過去的幾年裏，谷歌給 Dalvik 擴充了越來越多的更新，比如 JIT 支持、併發垃圾回收，以及多進程支持。但是隨着多核手機的出現，它們比 T-Mobile G1 快上很多倍，而這些功能升級擴充只能幫安卓到這裏了。</p><p>解決方案就是用 ART 這個安卓運行時替換 Dalvik，這是一個完全為現代智能手機硬件重寫的應用引擎。ART 更強調性能表現和用户界面流暢度。ART 帶來了一個從 JIT（Just-in-time，即時）編譯到 AOT（Ahead-of-time，提前）編譯的轉變。JIT 會在每次應用運行的時候即時編譯，節省存儲空間，因為編譯後的代碼從不寫入存儲，但它消耗更多的 CPU 和內存資源。AOT 會將編譯後的代碼保存到存儲，讓應用啓動的時候更快並減少內存使用。ART 會在設備上將編譯代碼作為安裝的一部分進行，而不分發預編譯的代碼，這樣編譯器可以進行一些針對特定設備的優化。ART 還帶來了 64 位支持，擴大了內存尋址範圍，由 64 位指令集帶來更佳的性能表現（特別是在媒體和加密應用上）。</p><p>而最好的部分是這個變化將這些性能優化和 64 位支持帶給了每個 java 安卓應用。ART 為每個 java 應用生成代碼，因此任何對 ART 的改進都自動應用到了這些應用。同時 ART 也是在未來的升級計劃下寫就，所以它能夠和安卓一同進化。</p><h4 id="一個系統層級的界面刷新" tabindex="-1">一個系統層級的界面刷新 <a class="header-anchor" href="#一個系統層級的界面刷新" aria-label="Permalink to “一個系統層級的界面刷新”">​</a></h4><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/systemui150-1-150x150.jpg" alt=""></p><p>Material Design 帶來了一個幾乎對安卓所有界面的完全翻新。首先，整個核心系統界面改變了。安卓得到了一個全新的按鈕集合，看起來有點像是 PlayStation 的手柄：三角形，圓形以及正方形按鈕，分別代表後退，主屏幕，和最近應用。得益於全新的圖標集，狀態欄也是煥然一新。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/lock-1-150x150.jpg" alt=""></p><p>最近應用獲得了大翻新。從一個小略縮圖縱向列表變成了一個巨大的，幾乎全屏的略縮圖串聯列表。它還獲得了一個新名字（也沒那麼守舊），“概覽（Overview）”。這明顯是受到了前面版本的 Chrome 標籤頁切換器效果的啓發。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/recent-apps-150x150.jpg" alt=""></p><p>順帶一説，在這個安卓版本里 Chrome 的標籤頁切換器效果消失了。作為一種將 Web 應用與本地應用同等對待的嘗試，Chrome 標籤合併到了概覽列表。是的：最近“應用”列表現在顯示的是最近打開的應用，加上最近打開的網站。在棒棒糖中，最近應用列表還採取了一種“以文檔為中心”的方法，意味着應用可以在最近應用列表中顯示多個項目。比如你在 Google Docs 中打開了兩個文檔，它們都會顯示在最近應用中，讓你可以在它們之間輕鬆切換，而不用到應用的文件列表去來回切換。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/recent2-150x150.jpg" alt=""></p><p>通知面板是全新的。谷歌給通知面板帶來了“卡片”主題，將每個項目歸整到它自己的矩形中。單個通知條目從黑色背景變成了白色背景，有了更佳的排版和圓形圖標。這些新通知來到了鎖屏上，將它從一個最沒用的中間屏變成了很有用的屏幕，用於展示“這裏是你不在的時候發生的事情”。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/notification-1-150x150.jpg" alt=""></p><p>全屏的通知，比如來電以及鬧鐘，都被拋棄了，取而代之的是在屏幕頂部彈出一個“抬頭（HUD）”通知。抬頭通知也對“高優先級”應用可用，最初這是為即時消息設計的。但是否是高優先級的通知這取決於開發者的決定，在開發者意識到這可以讓他們的通知更顯眼之後，所有人都開始使用它。之後版本的安卓通過給用户提供“高優先級”的設置解決了這個問題。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/headsup-1-150x150.jpg" alt=""></p><p>谷歌還給棒棒糖添加了一個單獨的，但很相似的“優先”通知系統。“優先”通知是一個介於完全靜音和“提醒一切消息”之間的模式，允許用户將特定的聯繫人和應用標記為重要。優先模式只會為這些重要的人發出提醒。在界面上來看，它採用了音量控制附加通知優先級控制以及設置中心添加一項優先通知新設置的形式。當你處在優先模式的時候，狀態欄會有一顆星形標識。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/panels-150x150.jpg" alt=""></p><p>快速設置獲得了一系列的大改善。控制項現在是一塊在通知_上面_的面板，所以它可以通過“兩次下拉”手勢來打開它。第一次下拉會打開通知面板，第二次下拉手勢會縮小通知面板並打開快速設置。快速設置的佈局變了，拋棄了平鋪排列，轉為一個單獨面板上的一系列浮動按鈕。頂部是十分方便的亮度調節條，之後是連接，自動旋轉，手電筒，GPS，以及 Chromecast 的按鈕。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/noticontrols-150x150.jpg" alt=""></p><p>快速設置現在還有了實際的內嵌面板。它可以在主界面顯示無線網絡接入點，藍牙設備，以及移動數據使用量。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/4-150x150.jpg" alt=""></p><p>Material Design 革新給了幾乎每個應用一個新圖標，並帶來了一個更明亮，白色背景的應用抽屜。默認應用陣容也有了很大的變化。和這些新應用問聲好吧：通訊錄，谷歌文檔，Fit，信息，照片，Play 報亭，以及谷歌幻燈片。和這些死去的應用説再見吧：相冊，G+ 照片，People，Play 雜誌，電子郵件，以及 Quickoffice。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/gmail2-150x150.jpg" alt=""></p><p>這些新應用中很多來自 Google Drive，從一個單獨的大應用分割成每個產品一個應用。現在我們有了雲端硬盤，文檔，表格，以及幻燈片，都來自於雲端硬盤團隊。雲端硬盤同時也要對 Quickoffice 的死亡負責，雲端硬盤團隊令它元氣大傷。在“谷歌從來沒法做好決定”分類下：通訊錄從“People”改回了“Contacts”，短信應用在運營商的要求下叫回了“Messenger”。（那些運營商_不_喜歡谷歌環聊插手短信的職能。）我們有項真正的新服務：谷歌健身，一個健康追蹤應用，可以在安卓手機和安卓手錶上工作。Play 雜誌也有了新的設計，添加了網站內容，所以它改名叫“Play 報亭”。</p><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/fit-150x150.jpg" alt=""><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/messages-1-150x150.jpg" alt=""><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/googl1-150x150.jpg" alt=""><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/2-150x150.jpg" alt=""><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/10/reminers-150x150.png" alt=""></p><p>還有更多的谷歌專有應用接管 AOSP 的例子。</p>',28)),n("ul",null,[n("li",null,[t[1]||(t[1]=o("“G+ 照片”變成了“谷歌照片”，並取代了 AOSP 的相冊成為默認照片應用，而相冊也就隨之消亡了。改名成“谷歌照片”是為照片應用",-1)),a(e,{href:"http://arstechnica.com/gadgets/2015/05/google-photos-leaves-google-launches-as-a-standalone-service/"},{default:p(()=>[...t[0]||(t[0]=[o("退出 Google+",-1)])]),_:1}),t[2]||(t[2]=o("併成為獨立服務做準備。谷歌照片的發佈在棒棒糖發佈之後六個月——暫時應用只像是 Google+ 應用換了個圖標和界面設計。",-1))]),t[3]||(t[3]=n("li",null,"Gmail 從電子郵件應用接管了 POP3，IMAP 以及 Exchange 郵件的任務。儘管死掉的電子郵件應用還有個圖標，但那是假的——它僅僅只顯示一條信息，告訴用户從 Gmail 應用設置電子郵件賬户。",-1)),t[4]||(t[4]=n("li",null,"“People”到“Contacts”的變化實際上是變為谷歌通訊錄，又是一個取代 AOSP 對應應用的例子。",-1))]),t[19]||(t[19]=n("hr",null,null,-1)),n("p",null,[t[6]||(t[6]=o("via: ",-1)),a(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/28/"},{default:p(()=>[...t[5]||(t[5]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/28/",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=o("作者：",-1)),a(e,{href:"http://arstechnica.com/author/ronamadeo/"},{default:p(()=>[...t[7]||(t[7]=[o("RON AMADEO",-1)])]),_:1}),t[11]||(t[11]=o(" 譯者：",-1)),a(e,{href:"https://github.com/alim0x"},{default:p(()=>[...t[8]||(t[8]=[o("alim0x",-1)])]),_:1}),t[12]||(t[12]=o(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[9]||(t[9]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=o("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[13]||(t[13]=[o("LCTT",-1)])]),_:1}),t[16]||(t[16]=o(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:p(()=>[...t[14]||(t[14]=[o("Linux中國",-1)])]),_:1}),t[17]||(t[17]=o(" 榮譽推出",-1))])])}const C=i(g,[["render",h]]);export{P as __pageData,C as default};
